async function swCommand(type){if(!('serviceWorker'in navigator))throw new Error('SW_UNAVAILABLE');const reg=await navigator.serviceWorker.ready,target=reg.active||navigator.serviceWorker.controller;if(!target)throw new Error('SW_NOT_ACTIVE');return new Promise((resolve,reject)=>{const c=new MessageChannel(),timer=setTimeout(()=>reject(new Error('SW_COMMAND_TIMEOUT')),8000);c.port1.onmessage=e=>{clearTimeout(timer);e.data?.ok?resolve(e.data):reject(new Error(e.data?.error||'SW_COMMAND_FAILED'))};target.postMessage({type},[c.port2])})}
async function deletePush(){const state=$('#push-state');try{await swCommand('SOS_PUSH_DELETE_REMOTE')}catch{}try{const reg='serviceWorker'in navigator?await navigator.serviceWorker.ready:null,sub=reg?await reg.pushManager.getSubscription():null;if(sub)await sub.unsubscribe()}catch{}localStorage.removeItem('sos-push-subscription-id');localStorage.removeItem('sos-push-zone-id');navigator.serviceWorker?.controller?.postMessage({type:'SOS_PUSH_CREDENTIAL_CLEAR'});state.textContent='Avisos desactivados y datos de suscripción eliminados.'}
$('#push-optin').onclick=enablePush;$('#push-test').onclick=async()=>{const state=$('#push-state');try{await swCommand('SOS_PUSH_SELF_TEST');state.textContent='Prueba enviada. El aviso indica explícitamente que no es una emergencia.'}catch{state.textContent='No se pudo enviar la prueba de avisos.'}};$('#push-delete').onclick=deletePush;
addEventListener('online',()=>{$('#network-state').textContent='Conexión restablecida.';updateVerification();Promise.all([loadOverview({animate:true}),load(),loadSourcesData()])});addEventListener('offline',()=>{$('#network-state').textContent='Sin conexión. Mostrando información guardada. No se puede verificar el estado actual.';updateVerification()});
async function swGeneration(target){return new Promise(resolve=>{const c=new MessageChannel(),timer=setTimeout(()=>resolve(null),700);c.port1.onmessage=e=>{clearTimeout(timer);resolve(e.data?.release||null)};try{target.postMessage({type:'APHORA_SHELL_GENERATION'},[c.port2])}catch{clearTimeout(timer);resolve(null)}})}
async function ensureShellGeneration(){const marker=document.querySelector('meta[name="aphora-release"]')?.content;if(!marker||marker.includes('__ORDER031_RELEASE_ID__')||!('serviceWorker'in navigator))return;try{const reg=await navigator.serviceWorker.register('/service-worker.js');const target=navigator.serviceWorker.controller;if(!target)return;const active=await swGeneration(target);if(active===marker)return;const guard=`aphora-shell-reload:${marker}`;if(sessionStorage.getItem(guard)==='1')return;sessionStorage.setItem(guard,'1');await reg.update().catch(()=>{});await new Promise(resolve=>{let done=false,finish=()=>{if(done)return;done=true;resolve()};navigator.serviceWorker.addEventListener('controllerchange',finish,{once:true});setTimeout(finish,900)});location.reload()}catch{}}
if('serviceWorker'in navigator)addEventListener('load',()=>ensureShellGeneration());show('now');loadOverview();load();
